package auth

import "testing"

// This hash string was generated by the pre-rewrite Node version (node:crypto scrypt,
// same parameters); it guarantees old accounts can still log in with their original
// password after the migration.
const nodeGeneratedHash = "scrypt$32768$8$1$s163ra+//Jr/xapHVQBItQ==$1m7Hhu/9baIFdr0Pze6LZp18RIDIt+aity38wMIAYslA4mXeXyav1MZkrLCP/ojqd7wEpjE5xkqjE9sF8HHa5Q=="

func TestVerifyPasswordAcceptsNodeGeneratedHash(t *testing.T) {
	if !VerifyPassword("test12345", nodeGeneratedHash) {
		t.Fatal("scrypt hash generated by Node failed verification in Go")
	}
	if VerifyPassword("wrong-password", nodeGeneratedHash) {
		t.Fatal("a wrong password must not verify")
	}
}

func TestHashPasswordRoundTrip(t *testing.T) {
	hash, err := HashPassword("correct horse battery staple")
	if err != nil {
		t.Fatalf("HashPassword: %v", err)
	}
	if !VerifyPassword("correct horse battery staple", hash) {
		t.Fatal("self-generated hash failed verification")
	}
	if VerifyPassword("Correct horse battery staple", hash) {
		t.Fatal("a differently-cased password must not verify")
	}
}

func TestVerifyPasswordRejectsMalformedHashes(t *testing.T) {
	cases := []string{
		"",
		"plain-text",
		"bcrypt$1$2$3$4$5",
		"scrypt$notanumber$8$1$c2FsdA==$aGFzaA==",
		"scrypt$32768$8$1$!!!$aGFzaA==",
		"scrypt$32768$8$1$c2FsdA==",
		// Parameters tampered into huge values must be rejected outright, not OOM the process
		"scrypt$999999999$8$1$c2FsdA==$aGFzaA==",
	}
	for _, stored := range cases {
		if VerifyPassword("anything", stored) {
			t.Fatalf("a malformed hash must not verify: %q", stored)
		}
	}
}

func TestRandomTokenIsURLSafe(t *testing.T) {
	token, err := randomToken()
	if err != nil {
		t.Fatal(err)
	}
	if len(token) != 43 {
		t.Fatalf("token length should be 43, got %d", len(token))
	}
	for _, r := range token {
		valid := r == '-' || r == '_' ||
			(r >= '0' && r <= '9') || (r >= 'A' && r <= 'Z') || (r >= 'a' && r <= 'z')
		if !valid {
			t.Fatalf("token contains a non-base64url character: %q", r)
		}
	}
}
